import type { Chapter } from './chapters'

export const systemsChapters: Record<string, Chapter> = {
  diffusion: {
    prerequisites: ['probability', 'training', 'convolution'], objectives: ['Calculate forward noising at a chosen timestep.', 'Explain what a denoiser learns and how sampling differs.', 'Compare diffusion with VAEs and GANs.'],
    sections: [
      { title: 'Generative modeling is learning a distribution', paragraphs: ['A discriminative model predicts targets from inputs. A generative model represents how plausible data can be produced, often conditioned on a label, text, or another observation. Autoregressive models do this through next-token conditionals; diffusion uses a sequence of noising and denoising steps.', 'Generating a plausible image is not the same as recovering the exact training example that produced a noisy observation. The objective concerns a data distribution, and sampling uses randomness to choose among plausible outcomes.'] },
      { title: 'Forward diffusion adds controlled Gaussian noise', paragraphs: ['At each forward step, shrink the previous sample slightly and add Gaussian noise. Let alpha_t=1-beta_t and alpha-bar_t be the product of alphas through timestep t. A useful identity lets us sample a noisy version directly from the clean sample without executing every intermediate step.', 'The square-root coefficients preserve a particular variance relationship under the assumed noise process. Alpha-bar measures cumulative retained signal, not the standard deviation itself.'], equation: String.raw`x_t=\sqrt{\bar\alpha_t}x_0+\sqrt{1-\bar\alpha_t}\epsilon,\quad\epsilon\sim\mathcal N(0,I)`, example: 'If alpha-bar=0.36, clean coefficient is 0.6 and noise coefficient is 0.8. For scalar clean value 0.5 and sampled noise -1, noisy value is 0.6*0.5+0.8*(-1)=-0.5.' },
      { title: 'Train a network to estimate the corruption', paragraphs: ['Sample a clean example, a timestep, and Gaussian noise. Construct x_t and ask a timestep-conditioned network to predict the noise. A common simplified objective is mean squared error between sampled noise and predicted noise.', 'Other parameterizations predict clean data, a velocity-like combination, or a score. They are related under a specified process but have different numerical behavior. A U-Net or transformer denoiser must receive timestep information because the same noisy value means different things at different noise levels.'], equation: String.raw`L=\mathbb E_{x_0,t,\epsilon}\left[\|\epsilon-\epsilon_\theta(x_t,t)\|^2\right]` },
      { title: 'Reverse sampling uses repeated learned estimates', paragraphs: ['Begin with random noise and repeatedly use the denoiser with a chosen reverse-process sampler to move toward data. The exact update depends on the noise schedule, parameterization, variance choices, and sampler; it is not simply subtracting the same predicted noise repeatedly.', 'Classifier-free guidance combines conditional and unconditional predictions, commonly epsilon_uncond+s*(epsilon_cond-epsilon_uncond). Larger guidance can strengthen prompt adherence but reduce diversity or introduce artifacts. Latent diffusion performs the process in an autoencoder latent space, reducing cost while adding reconstruction limitations.'] },
      { title: 'Other generative families solve a different objective', paragraphs: ['A VAE uses an encoder distribution, decoder likelihood, and a KL-regularized evidence lower bound. It trades reconstruction against a structured latent prior. A GAN trains a generator against a discriminator in an adversarial game and can face unstable training or mode collapse.', 'Diffusion often trades many sampling steps for stable supervised denoising training. None dominates every task. Evaluate distribution coverage, fidelity, conditioning, memorization, and latency rather than only one visually pleasing sample.'], question: 'Does the forward-noise lab demonstrate a trained reverse diffusion model?', answer: 'No. It computes the known corruption process. Recovering new samples requires a trained denoiser and a specified reverse sampler; those are separate components.' },
    ], application: 'Diffusion supports image, audio, video, and scientific generative tasks. The forward equation gives a clean foundation for understanding denoising objectives and their limits.', experiment: 'Hold the noise realization fixed and vary alpha-bar. Calculate the signal and noise coefficients, then explain why reducing visible noise is not the same as training a generative model.', next: 'reinforcement',
  },
  reinforcement: {
    prerequisites: ['probability', 'gradient'], objectives: ['Define states, actions, policies, rewards, and returns.', 'Calculate a Bellman target and policy-gradient direction.', 'Distinguish learning a reward-maximizing policy from learning human intent.'],
    sections: [
      { title: 'Actions affect future training data', paragraphs: ['In reinforcement learning, an agent observes a state or observation, chooses an action, receives a reward, and transitions. A policy maps available information to an action distribution. Unlike ordinary supervised data, the agent behavior influences which experiences it gathers.', 'A Markov decision process assumes the current state contains the information needed to describe future transitions given an action. Real observations may be partial, requiring memory or belief-state reasoning. Rewards are supplied by the task design; they are not automatically equivalent to what a user truly values.'] },
      { title: 'Optimize a return, not only the immediate reward', paragraphs: ['A discounted return sums future rewards with powers of gamma. Discounting can express time preference and help convergence in continuing tasks. The state value is expected return following a policy; the action value conditions additionally on taking a particular first action.', 'Delayed rewards create a credit-assignment problem. A locally costly action may improve eventual outcomes. Greedy immediate reward is therefore not generally an optimal policy.'], equation: String.raw`G_t=\sum_{k=0}^{\infty}\gamma^kr_{t+k+1},\quad V^\pi(s)=\mathbb E_\pi[G_t\mid s_t=s]`, example: 'Rewards [1,2,3] with gamma=0.9 give return 1+0.9*2+0.81*3=5.23. The immediate reward alone is only 1.' },
      { title: 'Bellman recursion relates neighboring decisions', paragraphs: ['A value can be written as immediate reward plus discounted next-state value in expectation. Temporal-difference methods use a sampled transition and a bootstrap estimate instead of waiting for a complete episode.', 'A Q-learning target uses reward plus gamma times the maximum next-action Q value for nonterminal transitions. For a truly terminal state, the future bootstrap term is zero. Time-limit truncation may need different handling because the underlying process may not actually terminate.'], equation: String.raw`Q(s,a)\leftarrow Q(s,a)+\alpha\left[r+\gamma\max_{a'}Q(s',a')-Q(s,a)\right]`, example: 'Current Q=2, reward=1, gamma=0.9, best next Q=3, rate=0.1: target=3.7, TD error=1.7, updated Q=2.17.' },
      { title: 'Policy gradients directly adjust action probabilities', paragraphs: ['The score-function identity gives a gradient estimate involving grad log policy times return. Actions associated with better-than-baseline outcomes receive pressure toward higher probability. A baseline can reduce variance without changing the expected gradient under appropriate conditions.', 'Actor-critic methods learn a value estimate to help estimate advantage. PPO constrains updates with a clipped probability-ratio objective, trying to avoid destructive policy changes. Clipping is a heuristic surrogate, not an unconditional safety or convergence guarantee.'], equation: String.raw`\nabla_\theta J\approx\mathbb E[\nabla_\theta\log\pi_\theta(a_t\mid s_t)\,\hat A_t]` },
      { title: 'Exploration and evaluation need care', paragraphs: ['An agent must sometimes try uncertain actions to learn their effects. Exploration can be expensive or unsafe in real environments, so simulators, offline data, action constraints, and staged deployment matter.', 'A policy can exploit a misspecified reward or simulator artifact. Evaluate actual task outcomes on held-out conditions and inspect behavior, not just average reward. Offline RL additionally faces distribution shift when choosing actions absent from the recorded data.'], question: 'If reported reward rises while users are less satisfied, has reinforcement learning failed mathematically?', answer: 'It may be optimizing exactly the supplied reward. The reward was an imperfect proxy, so mathematical success on it need not mean success on the intended task.' },
    ], application: 'RL supports control, games, resource allocation, and some language-model post-training. Its central difficulty is the interaction between action selection, delayed feedback, and imperfect objectives.', experiment: 'Compute the return and Q update above, then change the terminal flag. Explain why adding a nonexistent future value at an actual terminal state biases the estimate.', next: 'alignment',
  },
  alignment: {
    prerequisites: ['pretraining', 'reinforcement', 'probability'], objectives: ['Separate supervised demonstrations from preference optimization.', 'Explain reward modeling, KL constraints, and DPO.', 'Recognize proxy failures and evaluation limits.'],
    sections: [
      { title: 'Prediction ability does not determine desired behavior', paragraphs: ['A pretrained language model learns to predict text. It does not automatically know which response style, risk trade-off, or task interpretation a particular product should prefer. Post-training modifies behavior using demonstrations, comparisons, feedback, and evaluations.', 'Alignment is not a single scalar property obtained by finishing one optimization run. Different users and tasks have different needs, and behavior can change under distribution shift. State what outcomes and constraints are being evaluated.'] },
      { title: 'Learn a preference score from comparisons', paragraphs: ['Human raters or another process compare candidate responses to the same prompt. A reward model assigns scalar scores so preferred responses are more likely under a pairwise comparison model.', 'These scores are relative learned preferences, not calibrated truth probabilities. Rater instructions, disagreement, response length, presentation order, and annotation quality can all shape the learned model. AI-generated feedback changes the source of supervision but does not remove these concerns.'], equation: String.raw`P(y_+\succ y_-\mid x)=\sigma(r_\phi(x,y_+)-r_\phi(x,y_-))`, example: 'If preferred-response score is 2 and alternative score is 1, modeled preference probability is sigmoid(1), about 0.731. Doubling both scores by adding the same constant changes nothing.' },
      { title: 'RLHF optimizes reward while limiting drift', paragraphs: ['A language-model policy can be optimized against the learned reward, often with a penalty for departing from a reference policy. The KL term discourages moving too far based on an imperfect reward signal.', 'Reward hacking occurs when the policy finds outputs that score well without satisfying the intended preference. More optimization against a fixed reward model can worsen this gap. Evaluation should include independent judgments and task-grounded checks rather than only the training reward.'], equation: String.raw`\max_\pi\mathbb E[r(x,y)]-\beta D_{KL}(\pi(\cdot\mid x)\|\pi_{ref}(\cdot\mid x))` },
      { title: 'DPO optimizes preference pairs directly', paragraphs: ['Direct Preference Optimization uses preferred and dispreferred responses with a reference model, avoiding an explicit separately trained reward model and an online RL loop in its basic formulation. It increases a preference log-ratio relative to the reference.', 'It still depends on preference data coverage and assumptions connecting the preference objective to the policy. It is not evidence that feedback is unnecessary or that every pair should be trusted equally. Sequence log probabilities must be calculated with consistent tokenization and masking.'], equation: String.raw`L_{DPO}=-\log\sigma\left(\beta\left[\log\frac{\pi_\theta(y_+\mid x)}{\pi_{ref}(y_+\mid x)}-\log\frac{\pi_\theta(y_-\mid x)}{\pi_{ref}(y_-\mid x)}\right]\right)` },
      { title: 'Assess benefits and regressions together', paragraphs: ['Evaluate helpfulness, factuality, instruction following, appropriate uncertainty, and task-specific safety. Measure over-refusal as well as unsafe compliance where these apply. A model that avoids every difficult question may look conservative while being unusable.', 'Prompt injection, tool permissions, privacy, and misuse controls also require system-level design. Preference training cannot substitute for access control or make every model-generated action trustworthy.'], question: 'Can a high reward-model score prove a response is factually correct?', answer: 'No. It proves only that this reward model assigns a high score. Factuality needs evidence, verification, or an evaluation designed to measure it.' },
    ], application: 'Post-training shapes assistant behavior, but deployment quality depends on both model choices and surrounding system controls. Independent evaluations are essential when optimizing a learned proxy.', experiment: 'Given two response pairs, calculate how changing the policy-to-reference log ratios changes DPO preference. Then identify a stylistic shortcut a reward model might learn that would not improve task correctness.', next: 'rag',
  },
  rag: {
    prerequisites: ['embeddings', 'gpt'], objectives: ['Trace ingestion, retrieval, reranking, and generation.', 'Calculate retrieval metrics and inspect citation support.', 'Handle stale data, permissions, and untrusted document content.'],
    sections: [
      { title: 'Give generation access to external evidence', paragraphs: ['Retrieval-augmented generation searches a corpus for relevant material and includes selected passages in the generator input. It can provide current or private information without training all that information into weights.', 'Retrieval and generation are separate systems. Retrieval can fail to find the right evidence; generation can misread good evidence. A plausible answer with a citation is not necessarily supported by that citation. Evaluate both stages.'] },
      { title: 'Ingest with provenance and useful boundaries', paragraphs: ['Parse documents, retain source IDs and metadata, split into chunks, and build an index. Chunk boundaries should preserve enough context for interpretation without overwhelming retrieval with unrelated text. Overlap can reduce boundary losses but increases duplication.', 'Keep document version, timestamp, access permissions, and stable source references. Tables, code, and headings often need structure-aware extraction. Poor parsing can destroy evidence before the embedding model ever sees it.'] },
      { title: 'Retrieve candidates, then refine', paragraphs: ['Sparse retrieval such as BM25 matches lexical evidence and often handles exact identifiers well. Dense retrieval compares learned embeddings and can match paraphrases. Hybrid retrieval combines both, usually with a defined rank-fusion or score-normalization strategy.', 'Approximate nearest-neighbor indices trade exact ranking for lower latency and memory. A reranker evaluates query-document pairs more deeply on a smaller candidate set. Apply authorization filters before exposing candidates to the model, not merely when displaying citations afterward.'], equation: String.raw`\operatorname{cos}(q,d)=\frac{q^Td}{\|q\|\|d\|}`, example: 'If q=[1,1] and d1=[1,0], cosine is about 0.707. For d2=[1,1], it is 1. These numbers measure the representation similarity, not whether a document is authoritative or current.' },
      { title: 'Build a bounded evidence context', paragraphs: ['Select diverse relevant passages within a token budget, label their sources, and ask the generator to ground claims in them. Handle missing evidence by requesting clarification, abstaining, or clearly separating unsupported inference.', 'Documents are untrusted data. A retrieved sentence telling the assistant to ignore its instructions is not a higher-priority command. Tool permissions and system policies must remain separate from corpus content. Retrieval can introduce prompt-injection risk even when search itself works correctly.'] },
      { title: 'Measure retrieval and answer quality separately', paragraphs: ['Recall@k asks what fraction of known relevant items were retrieved in the top k. Precision@k asks what fraction of the k results were relevant. Ranking metrics such as MRR or nDCG measure where useful results appear.', 'For generation, assess correctness, faithfulness to sources, citation coverage, citation support, abstention, and latency. Distinguish no answer in corpus from retrieval failure and from generation failure. Those cases need different fixes.'], example: 'If three documents are relevant and top five results include two of them, recall@5=2/3 and precision@5=2/5.', question: 'Does retrieving a correct source guarantee a grounded answer?', answer: 'No. The generator can ignore it, combine incompatible passages, or attach its citation to an unsupported claim. Check the claim against the cited passage.' },
    ], application: 'RAG suits document assistants, support systems, and evidence-based search. Freshness and access control are as important as semantic matching.', experiment: 'Edit the local corpus so one passage contains an exact answer and another only shares keywords. Inspect rankings and assembled context. The lab does not call an LLM, making retrieval behavior visible without inventing generated evidence.', next: 'agents',
  },
  agents: {
    prerequisites: ['rag', 'gpt'], objectives: ['Trace a tool-using control loop.', 'Separate model suggestions from authorized execution.', 'Design bounded state, recovery, and evaluation.'],
    sections: [
      { title: 'An agent is a system loop, not a new neuron type', paragraphs: ['A tool-using agent observes task state, proposes an action, executes an authorized tool, records the result, and chooses what to do next. The model supplies decisions inside an orchestration system.', 'A fixed workflow uses explicit branching chosen by the developer. An agent delegates some branching to the model. More autonomy can help open-ended tasks but also increases variability, latency, and error propagation. Use the least autonomy that fits the task.'] },
      { title: 'Tool schemas turn text into constrained requests', paragraphs: ['A tool definition specifies its name, purpose, arguments, and expected result. Validate generated arguments against a schema before execution. A well-formed request can still be semantically wrong or unauthorized.', 'Keep credentials and permission enforcement in the execution layer. Use allowlists, scoped identities, and explicit approval for consequential actions. A model-generated claim that the user approved something is not evidence of approval.'] },
      { title: 'Track state and stop conditions explicitly', paragraphs: ['Store the task goal, completed actions, pending decisions, and tool observations. Distinguish observations from model speculation. Long histories may need summaries, but summaries can lose details and should retain important source references.', 'Set budgets for steps, tokens, time, and cost. Stop on completion, lack of progress, repeated failures, or a request requiring user judgment. Retry only when the failure mode is plausibly transient; repeated identical actions can compound damage.'], example: 'A read-only search can often be retried safely. A payment or message-send requires an idempotency key or explicit duplicate detection, because a timeout may occur after the action already succeeded.' },
      { title: 'Treat retrieved instructions as untrusted', paragraphs: ['Web pages, documents, emails, and tool outputs may contain text attempting to redirect the agent. That content is evidence for the task, not authority to change system rules or disclose secrets.', 'Separate planning from permission checks, minimize exposed secrets, and validate the destination and scope of external actions. Human confirmation should describe the actual effect, not merely ask whether to "continue" with an opaque operation.'] },
      { title: 'Evaluate complete trajectories', paragraphs: ['Measure task success, tool choice, argument accuracy, unnecessary actions, recovery, cost, and policy adherence over full runs. One accurate final response can hide unauthorized or redundant intermediate actions.', 'Use controlled environments and replayable scenarios before deploying consequential tools. Multi-agent setups add coordination and communication costs; multiple agreeing models do not automatically provide independent evidence.'], question: 'If a tool call returns a timeout, is retrying always safe?', answer: 'No. The action may have completed while the response was lost. Use idempotency, read-back verification, or user confirmation appropriate to the operation.' },
    ], application: 'Agents can coordinate research, coding, and operational tasks when tools are well-scoped and outcomes verifiable. Reliability comes from the entire loop, not just a persuasive planning paragraph.', experiment: 'Draw a state machine for a read-only document research agent. Include no-results, conflicting-evidence, timeout, and budget-exhausted paths. Add a write action only after specifying its permission and duplicate-prevention rules.', next: 'multimodal',
  },
  multimodal: {
    prerequisites: ['vision', 'embeddings', 'transformer'], objectives: ['Explain how images and audio become model inputs.', 'Distinguish contrastive alignment from generative fusion.', 'Evaluate grounding and modality-specific limitations.'],
    sections: [
      { title: 'Different signals need compatible representations', paragraphs: ['Text begins as discrete tokens, images as pixel arrays, and audio as sampled waveforms. A multimodal model uses encoders or tokenizers to convert these into representations that can interact.', 'Sharing a vector dimension is not enough to align meaning. Training must establish correspondences, such as paired image-caption examples, synchronized audio-video, or task-specific supervision. Misaligned pairs teach incorrect relationships.'] },
      { title: 'Vision transformers tokenize patches', paragraphs: ['Divide an image into patches, flatten each patch, and project it to model width. Add position information and process the sequence with a transformer. A learned class token or pooling can summarize it for classification.', 'For H by W pixels and square patch size P dividing both dimensions, patch count is H*W/P squared. Smaller patches preserve finer detail but increase token count and pairwise attention cost. High resolution often requires cropping, tiling, or specialized architectures.'], equation: String.raw`T_{image}=\frac H P\frac W P`, example: 'A 224 by 224 image with 16 by 16 patches yields 14*14=196 patch tokens. Using 8 by 8 patches yields 784 tokens, four times more and approximately sixteen times as many dense pair interactions.' },
      { title: 'Contrastive alignment matches paired modalities', paragraphs: ['A CLIP-style objective increases similarity between matched image and text embeddings while decreasing similarity to mismatched batch examples. It commonly uses a temperature-scaled softmax classification objective in both directions.', 'This produces a shared retrieval space useful for matching and zero-shot classification through text prompts. It does not by itself generate a detailed explanation of an image or guarantee fine-grained counting and spatial reasoning.'], equation: String.raw`L_i=-\log\frac{\exp(\operatorname{sim}(v_i,t_i)/\tau)}{\sum_j\exp(\operatorname{sim}(v_i,t_j)/\tau)}` },
      { title: 'Generative fusion supplies visual or audio context', paragraphs: ['A vision-language generator can project image features into language-model-compatible tokens or use cross-attention to an encoder. Training teaches the decoder to use this conditioning when producing text.', 'Audio can be represented through spectrogram features or learned waveform encoders. Speech recognition maps audio to text; text-to-speech maps text and optional speaker context to audio. A shared interface should not obscure distinct data, latency, and evaluation requirements.'] },
      { title: 'Grounding must be tested directly', paragraphs: ['A model may answer from language priors while ignoring an image. Evaluate pairs where the image changes but text remains the same, and check tasks requiring real visual evidence. Small text, charts, occlusion, and unusual layouts expose different weaknesses.', 'Account for privacy, consent, and sensitive attributes in visual or audio inputs. A confident description is not proof of accurate identification, measurement, or diagnosis. Preserve uncertainty and use domain-specific validation for high-stakes settings.'], question: 'Can a model with excellent image-text retrieval automatically read every tiny label in a diagram?', answer: 'No. Global semantic alignment and high-resolution text recognition are different capabilities. Patch resolution, encoder training, and task supervision matter.' },
    ], application: 'Multimodal systems support image search, document understanding, accessibility, speech interfaces, and cross-modal generation. Performance depends on which evidence survives each encoder.', experiment: 'Calculate patch counts at two resolutions. Design one example where a caption prior suggests the wrong answer and only inspecting the image resolves it.', next: 'evaluation',
  },
  evaluation: {
    prerequisites: ['probability', 'classifiers', 'gpt'], objectives: ['Calculate classification and language-model metrics.', 'Separate calibration, correctness, and task success.', 'Design clean, representative comparisons with uncertainty.'],
    sections: [
      { title: 'Begin with the decision the metric supports', paragraphs: ['A metric compresses performance into a number, so choose what matters before measuring. Classification accuracy, retrieval recall, generation quality, latency, and harmful-error rate answer different questions.', 'Training data fits parameters; validation selects choices; the test set estimates final performance. Repeatedly selecting designs on the test set turns it into another validation set. Grouped and time-based splits may be needed to prevent leakage.'] },
      { title: 'A confusion matrix exposes asymmetric errors', paragraphs: ['True positives are correctly detected positives; false positives are negatives incorrectly flagged; false negatives are missed positives. Precision is the fraction of positive predictions that are correct. Recall is the fraction of actual positives detected.', 'F1 is their harmonic mean and does not include true negatives. For severe imbalance, a high accuracy or ROC-AUC can hide poor positive predictive value. Precision-recall curves and explicit operating thresholds often better reflect costs.'], equation: String.raw`P=\frac{TP}{TP+FP},\quad R=\frac{TP}{TP+FN},\quad F_1=\frac{2PR}{P+R}`, example: 'TP=30, FP=10, FN=20 give precision 0.75, recall 0.6, F1 approximately 0.667. A denominator of zero requires an explicit reporting convention.' },
      { title: 'Calibration measures whether confidence is trustworthy', paragraphs: ['A calibrated model assigning probability 0.8 should be correct roughly 80% of the time among comparable predictions. It can be accurate but overconfident, or calibrated but not very discriminative.', 'Reliability plots, proper scoring rules such as log loss and Brier score, and subgroup checks help assess confidence. Binned calibration error depends on binning and sample size. Calibration learned on one distribution may fail after a shift.'] },
      { title: 'Language-model metrics have limits', paragraphs: ['Per-token perplexity is the exponential of mean negative log likelihood when natural logs are used. It can be interpreted as an effective uncertainty scale, not literally the same number of equally plausible choices at every step.', 'Perplexities are not directly comparable across different tokenizers or data conventions. BLEU and ROUGE measure forms of text overlap and may miss valid paraphrases or reward shallow similarity. LLM-as-judge evaluations need rubrics, bias checks, and human or task-grounded calibration.'], equation: String.raw`\operatorname{PPL}=\exp\left(-\frac1T\sum_t\log p(s_t\mid s_{<t})\right)`, example: 'Mean negative log likelihood 1.5 nats gives perplexity exp(1.5), about 4.48. This does not mean factual accuracy is 1/4.48.' },
      { title: 'Report uncertainty and failure slices', paragraphs: ['Finite test sets produce noisy estimates. Bootstrap intervals or suitable statistical methods can quantify uncertainty; repeated random seeds reveal training variation. Paired comparisons on the same examples are often more informative than unrelated aggregate scores.', 'Inspect performance by domain, language, subgroup, difficulty, and sequence length. Check benchmark contamination and near duplicates. Report resource budget and latency along with quality when comparing architectures or serving techniques.'], question: 'A model predicts the majority class in a dataset that is 99% negative. Is 99% accuracy enough evidence of usefulness?', answer: 'No. It may detect none of the positives. Recall, precision, cost, and the actual purpose of the system are essential.' },
    ], application: 'Evaluation turns model claims into evidence. A useful report describes the dataset, split, metric, uncertainty, resources, and known failure modes rather than only one headline score.', experiment: 'Construct a ten-example confusion matrix and calculate precision and recall at two thresholds. For a generator, separate correctness, citation support, and style in the scoring rubric.', next: 'interpretability',
  },
  interpretability: {
    prerequisites: ['backprop', 'attention', 'evaluation'], objectives: ['Distinguish attribution, probing, and causal intervention.', 'Understand common explanation methods and assumptions.', 'Avoid treating plausible explanations as proof of mechanism.'],
    sections: [
      { title: 'An explanation must specify what it explains', paragraphs: ['Feature attribution asks which inputs are associated with a particular prediction. A probe asks whether information is decodable from representations. Mechanistic analysis seeks computations causing behavior. A generated verbal rationale may be useful but is not automatically a faithful record of computation.', 'Global explanations summarize a model across examples; local explanations concern one prediction. A simple global pattern can miss important local exceptions, while one local explanation may not generalize.'] },
      { title: 'Gradients measure local sensitivity', paragraphs: ['An input gradient indicates how a small perturbation would change a chosen output locally. Saturation can make this small even when a feature was important earlier in the computation. Gradient-times-input introduces a reference of zero, which may not be meaningful for every feature.', 'Integrated gradients accumulates gradients along a path from a baseline to the input. Its interpretation depends on the baseline and path; intermediate points may be unrealistic. These choices should be documented, not hidden behind a colorful heatmap.'], equation: String.raw`IG_i(x)=(x_i-x'_i)\int_0^1\frac{\partial F(x'+\alpha(x-x'))}{\partial x_i}\,d\alpha` },
      { title: 'Perturbation methods depend on realistic comparisons', paragraphs: ['Occlusion removes or replaces input regions and measures the effect. SHAP-style approaches allocate credit using coalition-based ideas with a chosen background distribution. Feature dependence and missing-feature semantics affect the result.', 'Replacing a word with a blank or a pixel patch with black can create out-of-distribution inputs. A dramatic prediction change may reflect the unrealistic perturbation as well as the removed information. Compare multiple baselines and domain-appropriate interventions.'] },
      { title: 'Probes reveal accessibility, not necessarily use', paragraphs: ['A classifier trained on hidden states may decode syntactic, factual, or demographic information. That shows the probe can extract it under its capacity and data assumptions. It does not prove the original network uses that information for its own output.', 'Activation patching and ablation intervene on internal states and measure causal effects under a particular experimental setup. Distribution shift from the intervention, redundant pathways, and choice of source examples still complicate interpretation.'] },
      { title: 'Attention maps are one intermediate, not the whole explanation', paragraphs: ['Attention weights show routing coefficients for specific value vectors. The output also depends on those values, output projections, residual paths, later layers, and the chosen target. Large attention to a token does not directly measure its total causal influence.', 'Use explanation methods to generate and test hypotheses. Sanity checks include randomized weights, changed targets, controlled input changes, and independent interventions. Human-plausible stories should not substitute for evidence.'], question: 'If a probe predicts sentiment from a layer, does that prove the model final answer depends on sentiment?', answer: 'No. The information may be present but unused. An appropriately designed intervention is needed to test its effect on the behavior of interest.' },
    ], application: 'Interpretability helps debug shortcuts, inspect failure modes, and investigate learned computation. High-stakes decisions still need direct validation and accountable system design.', experiment: 'Inspect one attention row, then change its value vectors while keeping its weights fixed. Explain why an identical attention heatmap can produce a different output.', next: 'mlops',
  },
  mlops: {
    prerequisites: ['training', 'evaluation'], objectives: ['Version the complete prediction pipeline.', 'Design release, monitoring, and rollback procedures.', 'Distinguish data drift, concept drift, and performance degradation.'],
    sections: [
      { title: 'A model file is only part of a reproducible system', paragraphs: ['A prediction depends on preprocessing, tokenizer, model weights, runtime, feature definitions, and postprocessing. Version these together with training data references, split logic, and configuration.', 'An experiment record should connect a result to its code, data, seed, hyperparameters, and artifacts. Track provenance without unnecessarily copying sensitive data into logs or public artifacts.'] },
      { title: 'Validate contracts before measuring accuracy', paragraphs: ['Check schemas, ranges, missing-value handling, category vocabularies, and timestamp assumptions. A model trained on meters but served centimeters may execute perfectly and still fail catastrophically.', 'Training-serving skew occurs when preprocessing or feature availability differs between training and inference. Use shared transformations where practical and test realistic serving examples. Include latency and memory limits in release criteria.'] },
      { title: 'Release with an escape path', paragraphs: ['Shadow deployment observes predictions without affecting decisions. A canary exposes a limited fraction of traffic. A/B testing compares outcomes under a randomized design when appropriate. Each has different risks and evidence.', 'Keep a known-good artifact and rollback process. Define thresholds for errors, latency, unexpected outputs, and task metrics before launch. Changing a model, tokenizer, prompt template, or retrieval index can all require a release review.'] },
      { title: 'Monitor distributions and outcomes separately', paragraphs: ['Data drift means input distributions change. Concept drift means the relationship between inputs and targets changes. Either may affect performance, but a detectable input shift does not prove the model has degraded.', 'Ground-truth outcomes can be delayed or selectively observed. Monitor proxies such as schema errors and confidence, but periodically obtain reliable outcome labels. A feedback loop can change the population the model sees, making naive comparisons misleading.'], example: 'A credit model may only observe repayment for approved applicants. Evaluating only that group cannot directly establish performance for rejected applicants, whose outcomes were never observed.' },
      { title: 'Retraining needs governance, not just a timer', paragraphs: ['Choose whether retraining is triggered by time, new data, drift, or measured degradation. Validate the new candidate against the deployed version and retain auditability of data changes.', 'Monitor privacy, security, costs, and failure reports alongside accuracy. Data retention, access controls, and deletion obligations apply to stored prompts, embeddings, logs, and checkpoints, not just original documents.'], question: 'Should every statistically significant feature shift automatically trigger deployment of a retrained model?', answer: 'No. First assess whether the shift matters for task performance and whether new labels are reliable. A retrained candidate still needs validation and a controlled release.' },
    ], application: 'MLOps makes model quality repeatable and maintainable. It connects experiments to real users through explicit contracts, monitoring, and recovery.', experiment: 'Write a release checklist for a document assistant covering tokenizer version, index permissions, held-out answer quality, latency, logging, and rollback. Identify which checks cannot be replaced by training loss.', next: 'cache',
  },
  cache: {
    prerequisites: ['gpt', 'multi-head'], objectives: ['Explain why earlier keys and values can be reused.', 'Calculate KV-cache memory for MHA and GQA.', 'Distinguish cache validity from model weight reuse.'],
    sections: [
      { title: 'Autoregressive decoding repeatedly extends a prefix', paragraphs: ['Without caching, generating each token can recompute the entire prefix through every layer. In a causal transformer with fixed weights and consistent positions, earlier token representations do not depend on newly appended tokens.', 'Their keys and values can therefore be stored. The next token computes a new query, key, and value and attends over stored plus new keys and values. Old queries are generally not required to produce the new output.'] },
      { title: 'Separate prefill from decode', paragraphs: ['Prefill processes the known prompt, often in parallel, and creates the initial cache. Decode processes one or a small number of new tokens at a time. The new query still compares against the available prefix, so per-token attention work grows with retained context.', 'Caching eliminates redundant prefix projections and intermediate recomputation, not the model dependence on previous tokens. A sliding-window architecture may evict older entries according to its defined attention pattern, changing what is accessible.'] },
      { title: 'Derive memory from the stored tensor dimensions', paragraphs: ['Store both K and V at each layer, for each batch item, retained token, KV head, and head coordinate. Multiply the number of values by bytes per stored value. Use the number of KV heads, not query heads, for grouped-query attention.', 'This formula excludes allocation overhead, block tables, padding, quantization metadata, model weights, temporary activations, and framework memory. It estimates payload memory, not total device usage.'], equation: String.raw`M_{KV}=2BLTH_{KV}d_hs\ \text{bytes}`, example: 'B=1, L=32, T=4096, 8 KV heads, head width 128, 2 bytes/value give 536,870,912 bytes, exactly 512 MiB. Using 32 KV heads instead would require 2 GiB for the payload.' },
      { title: 'Cache identity depends on the exact computation', paragraphs: ['A reusable prefix cache requires compatible model weights, adapters, tokenizer output, positions, attention configuration, and relevant precision behavior. Similar-looking text is insufficient if token IDs or templates differ.', 'Changing an earlier token invalidates downstream cached states. Sharing cached private prefixes across users also needs isolation and permission policies. Cache hits are an implementation optimization, not permission to reveal another user content.'] },
      { title: 'Validate incremental decoding against the reference', paragraphs: ['For a short sequence, compare logits from full-prefix evaluation with cached incremental evaluation at each position. They should agree within the expected floating-point tolerance for the same architecture and precision.', 'Off-by-one positions, missing masks, incorrect head grouping, and appending cache entries twice are common errors. For a multi-token decode chunk, causal visibility within the chunk still needs a mask aligned with the cached prefix.'], question: 'Does KV caching remove quadratic prefill attention cost for a brand-new long prompt?', answer: 'No. Prefill still needs the prompt attention computation unless another technique changes or optimizes it. Caching primarily avoids recomputation during subsequent decoding or exact prefix reuse.' },
    ], application: 'KV-cache capacity often limits concurrent long-context users. GQA, paged allocation, quantization, and admission control address different parts of this constraint.', experiment: 'Reproduce the 512 MiB example in the cache lab. Double tokens, batch size, or KV heads one at a time and explain the linear memory growth.', next: 'serving',
  },
  serving: {
    prerequisites: ['cache', 'compression'], objectives: ['Distinguish latency, throughput, and utilization.', 'Explain continuous batching, paged caches, and FlashAttention.', 'Understand exact speculative decoding and its limits.'],
    sections: [
      { title: 'Optimize the metric users actually experience', paragraphs: ['Time to first token includes queueing, prompt processing, and the first decode result. Inter-token latency measures the pace afterward. End-to-end latency includes output length. Throughput counts completed work per unit time, such as tokens per second.', 'A larger batch can improve device utilization while increasing queueing delay for an individual request. Report latency percentiles and workload details, not only peak throughput under a favorable synthetic batch.'] },
      { title: 'Prefill and decode stress hardware differently', paragraphs: ['Prefill performs larger matrix operations over many known tokens and can be compute-intensive. Single-token decode often spends substantial time reading weights and cache data relative to arithmetic, becoming memory-bandwidth sensitive.', 'The actual bottleneck depends on model, batch size, precision, context, and hardware. A roofline-style view compares arithmetic intensity with available compute and bandwidth. Reducing FLOPs alone may not improve a memory-bound operation.'] },
      { title: 'Schedule changing sequence lengths efficiently', paragraphs: ['Static batches wait for all requests to finish and can waste capacity as shorter sequences end. Continuous batching admits and retires requests between decode steps, improving utilization.', 'Paged KV-cache allocation stores logical token blocks in noncontiguous physical memory, reducing fragmentation and allowing flexible allocation. Chunked prefill can prevent a long prompt from monopolizing the device, but scheduling policies must balance fairness, throughput, and first-token latency.'] },
      { title: 'FlashAttention changes memory traffic, not the objective', paragraphs: ['A straightforward attention implementation materializes scores and probabilities in high-bandwidth memory. FlashAttention-style algorithms tile the computation and maintain online normalization statistics, avoiding those large intermediate writes.', 'For supported settings, the result is mathematically exact attention up to floating-point differences, not sparse or approximate attention. Arithmetic still has quadratic token interactions for dense prefill, although memory use and actual speed improve substantially on appropriate hardware.'] },
      { title: 'Speculative decoding verifies cheaper proposals', paragraphs: ['A small draft model proposes several tokens; a target model evaluates them in a batched verification step. An exact acceptance-and-correction algorithm can preserve the target sampling distribution while reducing expensive sequential target calls.', 'For proposal q and target p at a candidate token, an acceptance rule uses min(1,p/q), with a residual correction distribution after rejection. Simply accepting tokens whose top choice agrees is not the full exact sampling algorithm. Speed depends on draft cost, acceptance rate, batch shapes, and verification overhead.'], equation: String.raw`P(\text{accept proposed }x)=\min\left(1,\frac{p(x)}{q(x)}\right)`, question: 'Will a draft model with poor agreement always speed up the target?', answer: 'No. Frequent rejection and draft overhead can erase any gain. Benchmark the combined system on the intended workload.' },
    ], application: 'Serving combines model architecture with memory management and scheduling. Quantization, exact attention kernels, caching, and batching optimize different bottlenecks and should be measured together.', experiment: 'Compare two hypothetical systems: one with faster first token but slower output tokens, another with slower prefill but faster decode. Calculate which wins for ten-token versus thousand-token responses.', next: 'distributed',
  },
  distributed: {
    prerequisites: ['training', 'optimizers', 'serving'], objectives: ['Distinguish data, tensor, pipeline, and state sharding.', 'Calculate effective batch size and gradient scaling.', 'Reason about communication, recomputation, and failure recovery.'],
    sections: [
      { title: 'One device may not fit the work or the state', paragraphs: ['Training stores parameters, gradients, optimizer state, and activations. Larger models or batches can exceed device memory, while a single accelerator may take too long to process the required data.', 'Distributed training partitions data, model computation, or state across devices. The best strategy depends on memory capacity, interconnect bandwidth, topology, and operation sizes. More devices do not imply linear speedup.'] },
      { title: 'Data parallelism replicates the model', paragraphs: ['Each worker processes a different batch using a model replica, then gradients are aggregated so replicas apply compatible updates. With equally sized batches, averaging worker-mean gradients gives the global mean gradient.', 'If batch sizes or valid-token counts differ, unweighted averaging can be wrong. Loss reduction and gradient synchronization must match the desired global objective. Effective batch size also includes intentional gradient accumulation.'], equation: String.raw`B_{effective}=B_{micro}\times N_{workers}\times N_{accumulation}`, example: 'Microbatch 4 on 8 workers with 16 accumulation steps gives effective batch 512 examples, provided all contributions are scaled consistently. For variable-length language data, valid-token counts may be the more relevant denominator.' },
      { title: 'Tensor and pipeline parallelism divide computation', paragraphs: ['Tensor parallelism splits large operations or weight matrices across devices, requiring communication to combine partial results. It benefits from fast links and enough arithmetic per communication round.', 'Pipeline parallelism places different layers on different stages and streams microbatches through them. Idle pipeline bubbles, load imbalance, and activation transfers reduce efficiency. More microbatches can reduce bubbles but interact with memory and scheduling.'] },
      { title: 'Shard state and recompute activations', paragraphs: ['ZeRO-style strategies partition optimizer state, gradients, and eventually parameters across data-parallel workers. Fully sharded approaches gather parameters when needed and release them afterward, trading memory for communication.', 'Activation checkpointing discards selected forward intermediates and recomputes them during backward. It saves activation memory at extra compute cost. This differs from saving a training checkpoint to disk for recovery, despite the shared word "checkpoint."'] },
      { title: 'Communication and reproducibility are first-class concerns', paragraphs: ['Collectives such as all-reduce, all-gather, and reduce-scatter synchronize distributed work. Slow workers, unequal sequence lengths, and network contention can stall others. Overlap communication with computation where dependencies permit.', 'Save enough state to resume: model, optimizer, schedule, random generators, and data progress where feasible. Verify that restarting does not silently repeat or skip large portions of data. Floating-point reduction order can change results without indicating a mathematical bug.'], question: 'Does gradient accumulation require storing all microbatch activations until the final update?', answer: 'No. Each microbatch can run forward and backward, free its graph, and retain only accumulated parameter gradients. Some framework choices or retained-graph settings can change this behavior.' },
    ], application: 'Distributed training makes large workloads feasible but adds communication and correctness constraints. A correct single-device reference and explicit loss-scaling convention remain valuable.', experiment: 'Split four scalar gradients into two workers and compare weighted aggregation with the full mean. Repeat with unequal worker sample counts to see why equal worker averaging can be biased.', next: 'scaling',
  },
  scaling: {
    prerequisites: ['pretraining', 'evaluation', 'distributed'], objectives: ['Interpret empirical scaling relations and compute budgets.', 'Separate parameter, data, and inference-time scaling.', 'Avoid extrapolating a fit into an unsupported capability guarantee.'],
    sections: [
      { title: 'Scaling laws summarize measured trends', paragraphs: ['Within studied regimes, held-out language-model loss often decreases predictably as model size, training tokens, and compute increase. Power-law-like fits provide a way to plan experiments and allocate a budget.', 'They are empirical descriptions of a particular data mixture, architecture family, optimizer recipe, and evaluation distribution. A good fit over one range does not prove the same exponent or asymptote applies indefinitely.'] },
      { title: 'Separate model-limited and data-limited error', paragraphs: ['A simplified loss model includes an irreducible term plus contributions decreasing with parameter count N and training data D. Fit constants and exponents from measurements, not universal defaults.', 'If a model is too small, more data may yield diminishing returns; if undertrained, more parameters may be wasted. Compute-optimal allocation balances these effects subject to the training budget. The optimum for training cost can differ from the optimum for repeated inference cost.'], equation: String.raw`L(N,D)\approx E+A N^{-\alpha}+B D^{-\beta}` },
      { title: 'Compute approximations are useful with stated assumptions', paragraphs: ['A common dense-transformer training estimate is approximately 6*N*D floating-point operations for N parameters and D tokens. It captures forward and backward parameter-related work under simplifying assumptions.', 'Attention at long context, embeddings, sparse activation, optimizer updates, and implementation overhead can change the estimate. A mixture-of-experts model has total parameters and active parameters that must be distinguished; sparse computation does not eliminate routing, communication, or total weight storage.'], equation: String.raw`C_{train}\approx6ND\quad\text{for a rough dense-model estimate}`, example: 'N=100 million and D=1 billion gives roughly 6e17 FLOPs. Dividing by peak device FLOPs assumes perfect utilization, which real training does not achieve.' },
      { title: 'Data quality and inference budgets change the question', paragraphs: ['Deduplicated, relevant, diverse data can outperform a larger noisy corpus at the same token budget. Repeating data is not always equivalent to adding new independent data. Synthetic data can help or amplify teacher errors and reduce diversity.', 'At inference, more samples, search, verification, or longer reasoning can improve some tasks. Compare quality against actual latency and cost. Additional generated tokens can also repeat mistakes, so test whether the procedure truly provides new evidence.'] },
      { title: 'Loss improvements do not directly specify capabilities', paragraphs: ['A smooth improvement in token loss may translate into nonlinear changes on a thresholded task metric. Apparent emergence can depend on evaluation granularity, prompting, and sample size.', 'Use scaling fits to form predictions with uncertainty, then test them on held-out scale points and task evaluations. Do not treat an extrapolated curve as proof of reliability, reasoning mechanism, or a fixed date for a future capability.'], question: 'If two models have equal pretraining loss, must they have equal tool-use accuracy?', answer: 'No. Data mixture, post-training, architecture, prompting, and evaluation can produce different downstream behavior despite similar average token loss.' },
    ], application: 'Scaling analysis supports resource planning and disciplined experiments. Its value comes from quantified assumptions and predictive validation, not from declaring bigger always better.', experiment: 'Hold a rough compute budget fixed and compare two N,D allocations using C=6ND. Then list measurements needed to decide which allocation actually gives better held-out quality and lower serving cost.', next: 'research',
  },
  research: {
    prerequisites: ['scaling', 'interpretability', 'evaluation'], objectives: ['Turn a broad idea into a falsifiable hypothesis.', 'Design controlled comparisons and ablations.', 'Read research claims with attention to evidence and limitations.'],
    sections: [
      { title: 'Start with a question that can be wrong', paragraphs: ['"Make transformers better" is a direction, not an experiment. A falsifiable hypothesis specifies a change, comparison, metric, and conditions. For example: a grouped-query variant reduces decode memory at a stated quality tolerance on a stated task distribution.', 'Identify the strongest simple alternative explanation. An improvement may come from more data, more parameters, more compute, or better tuning rather than the proposed mechanism. Design the cheapest experiment that could distinguish these explanations.'] },
      { title: 'Match budgets and protect the comparison', paragraphs: ['Use a competitive baseline, comparable training and tuning budgets, fixed data splits, and appropriate repeated seeds. Report both successful and unsuccessful settings when selection affects the conclusion.', 'An ablation removes or changes one component to test its contribution. Removing a component can alter parameter count or optimization difficulty, so an informative ablation may need a matched-capacity or matched-compute control. A negative result narrows a claim; it is not automatically a failed project.'] },
      { title: 'Read a paper in layers', paragraphs: ['First identify the problem, claim, proposed mechanism, and strongest result. Then inspect equations, dataset construction, baselines, compute, evaluation, and limitations. Ask whether the evidence actually distinguishes the proposed explanation from alternatives.', 'Reproduce a small central result before expanding the architecture. Track dependencies and implementation conventions such as normalization order, tokenizer, masking, and loss reduction. Small differences can invalidate comparisons even when a diagram looks identical.'] },
      { title: 'Research directions come with concrete trade-offs', paragraphs: ['State-space and selective-scan models aim to process sequences with compact recurrent state and efficient training kernels. They trade direct token-to-token retrieval for structured state updates. Mixture-of-experts models increase capacity with sparse activation but require routing, load balancing, and communication.', 'Retrieval-augmented models externalize some information; longer-context models retain more within the prompt. Neither makes evidence quality irrelevant. Mechanistic interpretability, robustness, data curation, uncertainty, and efficient adaptation are research areas because important questions remain unresolved, not because one architecture has settled them.'] },
      { title: 'Make conclusions narrower than the evidence boundary', paragraphs: ['Separate observed results, interpretations, and speculation. Report uncertainty, failed settings, data permissions, resource costs, and known threats to validity. Release code and configurations when permitted so others can inspect the computation.', 'A benchmark improvement does not establish universal reasoning, general safety, or deployment readiness. A responsible research claim says what was tested, under which conditions, and what remains unknown.'], question: 'Your method improves one benchmark after trying twenty variants but uses the test set to select the winner. What is wrong with the reported comparison?', answer: 'Selection has overfit the test set. Use validation for selection and evaluate the chosen method on a genuinely held-out test or new dataset, with an honest account of the search budget.' },
    ], application: 'Research-level understanding means connecting mathematical mechanisms to controlled evidence. You can contribute by finding a clear failure, measuring a trade-off, improving a baseline, or reproducing an important result carefully.', experiment: 'Write a one-page proposal: hypothesis, baseline, dataset, compute budget, metric, disconfirming result, ablation, and likely confounders. Make the first experiment small enough to run before committing to a large training job.', next: 'functions',
  },
}